    "content": "package com.artificialintelligence.gcpinventory;\n\nimport picocli.CommandLine.Command;\nimport picocli.CommandLine.Option;\nimport picocli.CommandLine.ParentCommand;\n\nimport java.util.concurrent.Callable;\n\n@Command(\n        name = \"all\",\n        mixinStandardHelpOptions = true,\n        description = \"List organizations and projects in one invocation.\")\nfinal class AllCommand implements Callable<Integer> {\n\n    @ParentCommand\n    private GcpInventory root;\n\n    @Option(\n            names = \"--org\",\n            paramLabel = \"ORGANIZATION\",\n            converter = OrganizationIdConverter.class,\n            description = \"Only list projects under this organization ID (or organizations/ID).\")\n    private String organization;\n\n    @Option(\n            names = \"--filter\",\n            paramLabel = \"TEXT\",\n            description = \"Client-side, case-insensitive filter on IDs and display names.\")\n    private String filter;\n\n    @Override\n    public Integer call() throws Exception {\n        var organizations = root.withService(service -> service.listOrganizations(null, filter));\n        var projects = root.withService(service -> service.listProjects(organization, null, filter));\n        Output.all(organizations, projects, root.outputFormat(), root.commandLine().getOut());\n        return 0;\n    }\n}\n"
