    "name": "src/main/java/com/artificialintelligence/gcpinventory/AuthMode.java",
    "content": "package com.artificialintelligence.gcpinventory;\n\n/** Where CLI credentials come from. */\npublic enum AuthMode {\n    /** Try Application Default Credentials, then fall back to the gcloud CLI. */\n    AUTO,\n    /** Application Default Credentials only. */\n    ADC,\n    /** Access token from the gcloud CLI only. */\n    GCLOUD;\n\n    @Override\n    public String toString() {\n        return name().toLowerCase();\n    }\n}\n"
